'use client';
import {createPortal} from 'react-dom';
import {forwardRef, useEffect, useLayoutEffect, useRef, useSyncExternalStore, type HTMLAttributes, type RefObject} from 'react';
import {setRefs} from '../../utils/overlay';

/* Shared floating layer for Popover, Tooltip, HoverCard, Select and the menus: one positioning function (side,
   align, offsets, flip, shift, available height) and one dismiss stack (Escape, outside press, focus leaving).
   No floating-ui, no scroll lock. */

export type Side = 'top' | 'right' | 'bottom' | 'left';
export type Align = 'start' | 'center' | 'end';
export interface Placement {
  /** Preferred side of the anchor. Flips to the opposite side when it does not fit. Default `bottom`. */
  side?: Side;
  /** Alignment along the anchor's edge. `start` and `end` follow the reading direction. Default `center`. */
  align?: Align;
  /** Gap in px between the anchor and the panel. */
  sideOffset?: number;
  /** Shift in px along the anchor's edge. */
  alignOffset?: number;
  /** Minimum gap in px kept to the viewport edges. Default 8. */
  collisionPadding?: number;
}

const OPPOSITE = {top: 'bottom', bottom: 'top', left: 'right', right: 'left'} as const;

/** Positions a `position: fixed` panel against an anchor. Sets `left`/`top`, `data-side`, `data-align` and the
 *  `--anchor-width` and `--available-height` custom properties. Call again on resize and scroll. */
export function place(anchor: Element, panel: HTMLElement, {side = 'bottom', align = 'center', sideOffset = 0, alignOffset = 0, collisionPadding: pad = 8}: Placement) {
  const a = anchor.getBoundingClientRect(), root = document.documentElement, vw = root.clientWidth, vh = root.clientHeight;
  const rtl = getComputedStyle(anchor).direction === 'rtl';
  panel.style.left = panel.style.top = '0px'; // measure at the origin so the viewport edge cannot squeeze it
  const {width: w, height: h} = panel.getBoundingClientRect();
  const room = {top: a.top, bottom: vh - a.bottom, left: a.left, right: vw - a.right};
  const vertical = side === 'top' || side === 'bottom';
  if (room[side] - pad < (vertical ? h : w) + sideOffset && room[OPPOSITE[side]] > room[side]) side = OPPOSITE[side];
  const along = (lo: number, size: number, panelSize: number, flip: boolean) => align === 'center' ? lo + (size - panelSize) / 2 : (align === 'start') !== flip ? lo : lo + size - panelSize;
  let x: number, y: number;
  if (vertical) { y = side === 'top' ? a.top - h - sideOffset : a.bottom + sideOffset; x = along(a.left, a.width, w, rtl) + (rtl ? -alignOffset : alignOffset); }
  else { x = side === 'left' ? a.left - w - sideOffset : a.right + sideOffset; y = along(a.top, a.height, h, false) + alignOffset; }
  x = Math.max(pad, Math.min(x, vw - w - pad)); y = Math.max(pad, Math.min(y, vh - h - pad));
  const s = panel.style;
  s.left = x + 'px'; s.top = y + 'px';
  s.setProperty('--anchor-width', a.width + 'px');
  s.setProperty('--available-height', Math.max(0, vertical ? room[side] - sideOffset - pad : vh - 2 * pad) + 'px');
  panel.dataset.side = side; panel.dataset.align = align;
}

const noop = () => () => {};
/** False while hydrating server HTML (portals have no server markup to match), true on the client from then on. */
export const useHydrated = () => useSyncExternalStore(noop, () => true, () => false);

const useLayout = typeof document === 'undefined' ? useEffect : useLayoutEffect;

export interface FloatingProps extends HTMLAttributes<HTMLDivElement>, Placement {
  /** Returns the element to position against, read when it opens and on every reposition. */
  anchor: () => Element | null;
}

/** A fixed-position panel placed against an anchor. Rendered into the nearest open `<dialog>` (so it stays usable
 *  inside a modal) or `document.body`. Repositions on resize, scroll and size changes. */
export const Floating = forwardRef<HTMLDivElement, FloatingProps>(function Floating({anchor, side, align, sideOffset, alignOffset, collisionPadding, style, ...rest}, forwarded) {
  const el = useRef<HTMLDivElement | null>(null);
  useLayout(() => {
    const p = el.current!, go = () => { const a = anchor(); if (a) place(a, p, {side, align, sideOffset, alignOffset, collisionPadding}); };
    go();
    addEventListener('resize', go); addEventListener('scroll', go, true);
    const ro = typeof ResizeObserver === 'undefined' ? null : new ResizeObserver(go);
    ro?.observe(p);
    return () => { removeEventListener('resize', go); removeEventListener('scroll', go, true); ro?.disconnect(); };
  }, [side, align, sideOffset, alignOffset, collisionPadding]);
  if (typeof document === 'undefined') return null;
  return createPortal(<div ref={(n) => setRefs(n, el, forwarded)} style={{position: 'fixed', ...style}} {...rest} />, anchor()?.closest('dialog[open]') ?? document.body);
});

const layers: object[] = [];

/** While `open`, calls `dismiss` for Escape, a press outside every ref, or focus moving outside. Only the topmost
 *  layer reacts, so a menu inside a popover closes first. */
export function useDismiss(open: boolean, inside: Array<RefObject<Element | null>>, dismiss: (kind: 'escape' | 'outside', e: Event) => void) {
  const latest = useRef({inside, dismiss});
  latest.current = {inside, dismiss};
  useEffect(() => {
    if (!open) return;
    const me = {}; layers.push(me);
    const key = (e: KeyboardEvent) => { if (e.key === 'Escape' && layers[layers.length - 1] === me) { e.preventDefault(); latest.current.dismiss('escape', e); } };
    const out = (e: Event) => { if (layers[layers.length - 1] === me && !latest.current.inside.some((r) => r.current?.contains(e.target as Node))) latest.current.dismiss('outside', e); };
    document.addEventListener('keydown', key, true); document.addEventListener('pointerdown', out, true); document.addEventListener('focusin', out, true);
    return () => { document.removeEventListener('keydown', key, true); document.removeEventListener('pointerdown', out, true); document.removeEventListener('focusin', out, true); layers.splice(layers.indexOf(me), 1); };
  }, [open]);
}

/** Hover-intent timing for Tooltip and HoverCard: `show` and `hide` take effect after a delay (ms) unless the pointer
 *  comes back first. */
export function useHoverIntent(setOpen: (o: boolean) => void) {
  const timer = useRef<ReturnType<typeof setTimeout>>(undefined);
  useEffect(() => () => clearTimeout(timer.current), []);
  return (open: boolean, delay = 0) => { clearTimeout(timer.current); if (delay) timer.current = setTimeout(() => setOpen(open), delay); else setOpen(open); };
}

'use client';
import {createContext, forwardRef, useContext, useEffect, useId, useRef, type ButtonHTMLAttributes, type HTMLAttributes, type MouseEvent, type ReactNode, type RefObject} from 'react';
import {Slot} from '../../utils/slot';
import {useControllableState} from '../../hooks/use-controllable-state';
import {cx} from '../../utils/cx';
import {TABBABLE, setRefs, vetoed} from '../../utils/overlay';
import {Floating, useDismiss, useHydrated, type Placement} from './float';

interface Ctx { open: boolean; setOpen: (o: boolean) => void; contentId: string; trigger: RefObject<HTMLElement | null>; anchor: RefObject<HTMLElement | null> }
const Context = createContext<Ctx>(null as never);

export interface PopoverProps {
  /** Controlled open state. */
  open?: boolean;
  /** Initial open state when uncontrolled. Default false. */
  defaultOpen?: boolean;
  /** Called with the next open state when the user opens or dismisses it. */
  onOpenChange?: (open: boolean) => void;
  /** The parts of the component: a trigger and its content. */
  children?: ReactNode;
}

/** The root of a floating panel. Holds the open state (`open`, `defaultOpen`, `onOpenChange`); put a `PopoverTrigger` and `PopoverContent` inside. */
export function Popover({open, defaultOpen = false, onOpenChange, children}: PopoverProps) {
  const [isOpen, setOpen] = useControllableState({value: open, defaultValue: defaultOpen, onChange: onOpenChange});
  const trigger = useRef<HTMLElement | null>(null), anchor = useRef<HTMLElement | null>(null);
  return <Context.Provider value={{open: isOpen, setOpen, contentId: useId(), trigger, anchor}}>{children}</Context.Provider>;
}

interface AsChild { /** Render your own element instead of the default; it receives the props and handlers. */ asChild?: boolean }

/** The element (usually a `Button`) that toggles the popover; use `asChild` to render your own element. */
export const PopoverTrigger = forwardRef<HTMLButtonElement, ButtonHTMLAttributes<HTMLButtonElement> & AsChild>(function PopoverTrigger({asChild, onClick, ...rest}, ref) {
  const c = useContext(Context);
  const Comp = asChild ? Slot : 'button';
  return <Comp ref={(n: HTMLButtonElement | null) => setRefs(n, c.trigger, ref)} type={asChild ? undefined : 'button'} aria-haspopup="dialog" aria-expanded={c.open} aria-controls={c.open ? c.contentId : undefined} data-state={c.open ? 'open' : 'closed'} {...rest} onClick={(e: MouseEvent<HTMLButtonElement>) => { onClick?.(e); if (!e.defaultPrevented) c.setOpen(!c.open); }} />;
});

/** Positions the popover against this element instead of the trigger. */
export const PopoverAnchor = forwardRef<HTMLDivElement, HTMLAttributes<HTMLDivElement> & AsChild>(function PopoverAnchor({asChild, ...rest}, ref) {
  const c = useContext(Context);
  const Comp = asChild ? Slot : 'div';
  return <Comp ref={(n: HTMLDivElement | null) => setRefs(n, c.anchor, ref)} {...rest} />;
});

/** An element that closes the popover when activated; use `asChild` to wrap your own button. */
export const PopoverClose = forwardRef<HTMLButtonElement, ButtonHTMLAttributes<HTMLButtonElement> & AsChild>(function PopoverClose({asChild, onClick, ...rest}, ref) {
  const c = useContext(Context);
  const Comp = asChild ? Slot : 'button';
  return <Comp ref={ref} type={asChild ? undefined : 'button'} {...rest} onClick={(e: MouseEvent<HTMLButtonElement>) => { onClick?.(e); if (!e.defaultPrevented) c.setOpen(false); }} />;
});

export interface PopoverContentProps extends HTMLAttributes<HTMLDivElement>, Placement {
  /** Called when Escape is pressed; call `event.preventDefault()` to keep it open. */
  onEscapeKeyDown?: (event: Event) => void;
  /** Called when a press or focus lands outside; call `event.preventDefault()` to keep it open. */
  onInteractOutside?: (event: Event) => void;
  /** Called after it opens, before focus moves in; `preventDefault()` keeps focus where it is or lets you move it yourself. */
  onOpenAutoFocus?: (event: Event) => void;
  /** Called after it closes, before focus returns to the trigger; `preventDefault()` lets you move focus yourself. */
  onCloseAutoFocus?: (event: Event) => void;
}

const Panel = forwardRef<HTMLDivElement, PopoverContentProps>(function Panel({className, sideOffset = 8, align = 'start', side, onEscapeKeyDown, onInteractOutside, onOpenAutoFocus, onCloseAutoFocus, ...rest}, forwarded) {
  const c = useContext(Context);
  const el = useRef<HTMLDivElement | null>(null);
  const outside = useRef(false);
  const hooks = useRef({onOpenAutoFocus, onCloseAutoFocus});
  hooks.current = {onOpenAutoFocus, onCloseAutoFocus};
  useDismiss(true, [el, c.trigger, c.anchor], (kind) => {
    if (vetoed(kind === 'escape' ? onEscapeKeyDown : onInteractOutside, el.current!)) return;
    outside.current = kind === 'outside';
    c.setOpen(false);
  });
  useEffect(() => {
    const p = el.current!;
    if (!vetoed(hooks.current.onOpenAutoFocus, p)) (p.querySelector<HTMLElement>(TABBABLE) ?? p).focus();
    return () => { if (!vetoed(hooks.current.onCloseAutoFocus, p) && !outside.current) c.trigger.current?.focus(); };
  }, []);
  return <Floating ref={(n) => setRefs(n, el, forwarded)} anchor={() => c.anchor.current ?? c.trigger.current} side={side} align={align} sideOffset={sideOffset} role="dialog" id={c.contentId} tabIndex={-1} data-state="open" className={cx('popover', className)} {...rest} />;
});

/** A floating panel anchored to its trigger, placed on the side with room. Focus moves in, Escape closes and returns focus to the trigger, a press outside closes it. */
export const PopoverContent = forwardRef<HTMLDivElement, PopoverContentProps>(function PopoverContent(props, ref) {
  const {open} = useContext(Context), hydrated = useHydrated();
  return open && hydrated ? <Panel ref={ref} {...props} /> : null;
});
